mapper.update:
UPDATE attendance
clock_in_at = #{clockInAt}, clock_out_at = #{clockOutAt}, break_start_at = #{breakStartAt}, break_end_at = #{breakEndAt}, total_break_minutes = #{totalBreakMinutes}, net_work_minutes = #{netWorkMinutes}, night_work_minutes = #{nightWorkMinutes}, overtime_minutes = #{overtimeMinutes}, clock_in_method = #{clockInMethod}, attendance_status = #{attendanceStatus}, updated_at = CURRENT_TIMESTAMP
WHERE attendance_id = #{attendanceId}

mapper.select:
SELECT shift_id
FROM shift_schedule
WHERE store_staff_id = #{storeStaffId}
  AND work_date = #{workDate}
  AND status = 'CONFIRMED'
LIMIT 1

SELECT r.mod_request_id, r.attendance_id, r.store_id, r.store_staff_id, m.name AS staff_name, r.work_date, r.before_clock_in_at, r.before_clock_out_at, r.before_break_minutes, r.requested_clock_in_at, r.requested_clock_out_at, r.requested_break_minutes, r.reason, r.approval_status, r.reject_reason, r.created_at FROM attendance_mod_request r JOIN store_staff ss ON r.store_staff_id = ss.store_staff_id JOIN member m ON ss.member_id = m.member_id WHERE r.store_id = #{storeId}
AND r.approval_status = #{status}
ORDER BY r.mod_request_id DESC

SELECT mod_break_id AS attendance_break_id, mod_request_id AS attendance_id, break_set_type, break_start_at, break_end_at, duration_minutes FROM attendance_mod_break WHERE mod_request_id IN
#{id}
ORDER BY break_start_at ASC

SELECT COUNT(*)
FROM attendance
WHERE store_staff_id = #{storeStaffId}

      AND attendance_id != #{excludeAttendanceId}

  AND clock_in_at < #{clockOutAt}
  AND (clock_out_at IS NULL OR clock_out_at > #{clockInAt})

SELECT COALESCE(SUM(net_work_minutes), 0)
FROM attendance
WHERE store_staff_id = #{storeStaffId}
  AND work_date = #{workDate}
  AND attendance_status = 'COMPLETED'

      AND attendance_id != #{excludeAttendanceId}


      AND clock_out_at <= #{beforeTime}
